OUT.parent.mkdir(parents=True, exist_ok=True)

CSS = """
:root{--ink:#19243a;--muted:#5d6880;--line:#dce4f0;--blue:#2459a8;--pale:#edf3ff;--green:#eaf8ef;--amber:#fff4d8;--red:#fff0ed}
*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:var(--ink);font:16px/1.65 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
header{background:linear-gradient(130deg,#14294c,#2d67af);color:white;padding:38px max(20px,calc((100% - 980px)/2))}header p{color:#e2ecff;max-width:850px}
main{max-width:980px;margin:24px auto;padding:0 18px 44px}section{background:white;border:1px solid var(--line);border-radius:15px;padding:22px;margin:17px 0;box-shadow:0 3px 12px #16264708}
h1{font-size:clamp(2rem,4vw,3rem);line-height:1.12;margin:.4em 0}h2{color:#214e91;margin-top:0}h3{margin-bottom:5px}.tag{display:inline-block;border:1px solid #9dbcf0;border-radius:30px;padding:4px 10px;font-size:.82rem}
.callout{background:var(--pale);border-left:4px solid var(--blue);padding:13px 16px;border-radius:8px;margin:13px 0}.good{background:var(--green);padding:12px;border-radius:8px}.warn{background:var(--amber);padding:12px;border-radius:8px}
table{width:100%;border-collapse:collapse;margin:12px 0;font-size:.95rem}th,td{border:1px solid var(--line);padding:10px;text-align:left;vertical-align:top}th{background:#edf3fc}
.diagram{background:#f8faff;border:1px dashed #b5c8e8;border-radius:12px;padding:16px;margin:14px 0}.flow{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:9px}.box{background:white;border:2px solid #81a0d4;border-radius:10px;padding:12px;text-align:center;min-width:130px}.arrow{color:var(--blue);font-size:1.4rem}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.card{border:1px solid var(--line);padding:14px;border-radius:10px}.marks{background:#f0fbf4;border-left:4px solid #2c8b57;padding:13px 16px;border-radius:8px;margin:12px 0}.q{padding:12px 0;border-bottom:1px solid var(--line)}.answer{color:#246343;font-weight:600}.muted{color:var(--muted)}footer{text-align:center;color:var(--muted);padding:20px}
@media(max-width:650px){section{padding:16px}table{display:block;overflow-x:auto}}
"""
def sec(title, body):
    return f"<section><h2>{title}</h2>{body}</section>"

page = f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Topic 23 — Packet Fragmentation | Computer Networks</title><style>{CSS}</style></head><body>
<header><span class="tag">COMPUTER NETWORKS · UNIT 2</span><h1>23. Packet Fragmentation</h1><p>Visual notes on splitting packets to fit a network MTU, IPv4 fragmentation fields, reassembly, a worked calculation, and exam practice.</p></header><main>
<div class="callout"><strong>Study-source note:</strong> These notes explain standard IP fragmentation concepts. Check the prescribed Unit 2 PPT for its exact examples and depth. The worked numerical example below is illustrative.</div>
{sec("1. Learning objectives", """<ul><li>Define packet fragmentation and explain why it is needed.</li><li>Understand MTU and the effect of headers on packet size.</li><li>Explain the basic IPv4 fragmentation fields.</li><li>Work through a simple fragmentation calculation.</li><li>Distinguish fragmentation from segmentation and tunneling.</li></ul>""")}
{sec("2. What is packet fragmentation?", """<p><strong>Packet fragmentation</strong> is the process of dividing an IP packet into smaller fragments when the packet is too large to cross a network link with a smaller Maximum Transmission Unit (MTU). Each fragment is transmitted as a separate IP packet and carries information that supports reassembly at the destination.</p><div class="callout"><strong>MTU:</strong> the maximum size of a packet that a particular link-layer network can carry in one frame, according to that link's definition.</div><p>In IPv4, a router may fragment a packet when fragmentation is permitted and the packet exceeds the outgoing link's MTU. The destination host reassembles the fragments to recover the original IP datagram. In IPv6, routers do not fragment packets; the source uses a Fragment extension header when fragmentation is needed.</p>""")}
{sec("3. Why fragmentation happens", """<p>Different links can support different packet sizes. A packet created on a network with a larger MTU may encounter a later link whose MTU is smaller.</p><div class="diagram"><div class="flow"><div class="box">Large IP packet<br><small>e.g., 4000 bytes</small></div><span class="arrow">→</span><div class="box">Router checks<br>outgoing MTU</div><span class="arrow">→</span><div class="box">Smaller-MTU link<br><small>packet too large</small></div></div><div class="flow" style="margin-top:12px"><div class="box" style="border-color:#2b8a57">Fragment 1</div><div class="box" style="border-color:#2b8a57">Fragment 2</div><div class="box" style="border-color:#2b8a57">Fragment 3</div></div><p class="muted">Conceptual illustration only; actual fragment count depends on packet size, header size, and outgoing MTU.</p></div>""")}
{sec("4. IPv4 fragmentation fields", """<table><thead><tr><th>Field</th><th>Purpose</th><th>Remember</th></tr></thead><tbody><tr><td><strong>Identification</strong></td><td>Helps the destination identify fragments belonging to the same original datagram.</td><td>Fragments from one datagram share the relevant identification value.</td></tr><tr><td><strong>DF — Don't Fragment</strong></td><td>When set, the packet must not be fragmented by IPv4 routers.</td><td>If it cannot be forwarded due to MTU, it is dropped and an error can be reported.</td></tr><tr><td><strong>MF — More Fragments</strong></td><td>Indicates whether more fragments follow.</td><td>Set on all fragments except the final fragment.</td></tr><tr><td><strong>Fragment Offset</strong></td><td>Indicates the fragment's position in the original payload.</td><td>Measured in units of 8 bytes, not individual bytes.</td></tr><tr><td><strong>Total Length</strong></td><td>Length of this individual IPv4 fragment, including its IPv4 header.</td><td>Each fragment has its own IP header and total-length value.</td></tr></tbody></table>""")}
{sec("5. Worked numerical example", """<p><strong>Assume:</strong> an IPv4 datagram has a total length of 4000 bytes, including a 20-byte IPv4 header. The outgoing link MTU is 1500 bytes. Assume no IP options, so each fragment has a 20-byte header.</p><ol><li>Original data payload = 4000 − 20 = <strong>3980 bytes</strong>.</li><li>Maximum payload per fragment = 1500 − 20 = 1480 bytes. This is divisible by 8, as required for non-final fragment payloads.</li><li>Split payload: 1480 + 1480 + 1020 = 3980 bytes.</li><li>Fragment total lengths: 1500, 1500, and 1040 bytes.</li></ol>
<table><thead><tr><th>Fragment</th><th>Payload bytes</th><th>Total length</th><th>Fragment offset</th><th>MF bit</th></tr></thead><tbody><tr><td>1</td><td>1480</td><td>1500</td><td>0</td><td>1</td></tr><tr><td>2</td><td>1480</td><td>1500</td><td>185</td><td>1</td></tr><tr><td>3</td><td>1020</td><td>1040</td><td>370</td><td>0</td></tr></tbody></table>
<p><strong>Offset calculation:</strong> fragment 2 starts after 1480 payload bytes, so offset = 1480 ÷ 8 = 185. Fragment 3 starts after 2960 payload bytes, so offset = 2960 ÷ 8 = 370. DF is assumed to be 0 for this example.</p><div class="warn"><strong>Common mistake:</strong> offsets are expressed in 8-byte units and are measured from the beginning of the original payload. Do not divide total fragment length by 8.</div>""")}
{sec("6. How reassembly works", """<ol><li>Fragments travel independently and may arrive out of order.</li><li>The destination uses fields such as source, destination, protocol, and Identification to associate fragments with a datagram.</li><li>The Fragment Offset indicates where each fragment's payload belongs.</li><li>The MF flag helps identify the final fragment.</li><li>Once all required pieces arrive, the destination reassembles the original datagram. If fragments are missing, reassembly may fail and the incomplete datagram is eventually discarded.</li></ol><div class="callout">In IPv4, reassembly is normally performed at the destination host, not at every intermediate router.</div>""")}
{sec("7. IPv4 vs. IPv6 fragmentation", """<table><thead><tr><th>Aspect</th><th>IPv4</th><th>IPv6</th></tr></thead><tbody><tr><td>Router fragmentation</td><td>May be performed by routers if allowed by the DF flag and conditions.</td><td>Routers do not fragment packets.</td></tr><tr><td>Source fragmentation</td><td>Source can fragment packets.</td><td>Source can fragment using a Fragment extension header.</td></tr><tr><td>MTU discovery</td><td>Path MTU Discovery commonly uses DF behaviour to learn the path limit.</td><td>Path MTU Discovery is important because routers cannot fragment packets.</td></tr><tr><td>Reassembly</td><td>Performed at the destination.</td><td>Performed at the destination.</td></tr></tbody></table><p class="muted">If your syllabus focuses only on IPv4, prioritize its fields and calculations; use the IPv6 comparison as supporting context.</p>""")}
{sec("8. Fragmentation vs. segmentation vs. tunneling", """<table><thead><tr><th>Term</th><th>Meaning</th><th>Typical layer/context</th></tr></thead><tbody><tr><td><strong>IP fragmentation</strong></td><td>Splits one IP datagram into smaller IP fragments to fit an MTU.</td><td>Network layer</td></tr><tr><td><strong>Transport segmentation</strong></td><td>Divides application data into transport-layer segments.</td><td>Transport layer, e.g. TCP</td></tr><tr><td><strong>Tunneling</strong></td><td>Encapsulates one packet inside another packet for transport across an intermediate network.</td><td>Encapsulation across network domains</td></tr></tbody></table>""")}
{sec("9. Advantages and disadvantages", """<div class="grid"><div class="card"><h3>✅ Advantages</h3><ul><li>Allows an oversized IPv4 datagram to cross links with smaller MTUs when fragmentation is permitted.</li><li>Supports interoperability across networks with different MTU sizes.</li></ul></div><div class="card"><h3>⚠️ Disadvantages</h3><ul><li>Each fragment adds an IP header, increasing overhead.</li><li>Loss of one fragment can prevent delivery of the complete datagram.</li><li>Reassembly consumes destination resources.</li><li>Fragmentation can complicate filtering, performance, and troubleshooting.</li></ul></div></div>""")}
{sec("10. Exam-ready answers", """<div class="marks"><h3>3 marks — Define packet fragmentation.</h3><p>Packet fragmentation is the division of an IP datagram into smaller fragments when it exceeds the MTU of a link. Each fragment has its own IP header and is transmitted separately. The destination uses fragmentation information to reassemble the original datagram.</p></div>
<div class="marks"><h3>5 marks — Explain IPv4 fragmentation fields.</h3><p>Explain Identification, DF, MF, Fragment Offset, and Total Length. State that the offset is measured in 8-byte units, MF is set for fragments followed by more fragments, and DF prevents router fragmentation when set.</p></div>
<div class="marks"><h3>8–10 marks — Explain fragmentation with a numerical example.</h3><p>Define MTU and fragmentation. Draw a large datagram being split into fragments at a smaller-MTU link. Explain the IPv4 fields and show the payload/offset calculation. For example, a 4000-byte datagram with a 20-byte header crossing an MTU of 1500 bytes yields payload fragments of 1480, 1480, and 1020 bytes, with offsets 0, 185, and 370. Conclude with destination reassembly and disadvantages.</p></div>""")}
{sec("11. Practice questions", """<div class="q"><strong>Q1. What does MTU stand for?</strong><p class="answer">Maximum Transmission Unit.</p></div><div class="q"><strong>Q2. What is the unit of the IPv4 Fragment Offset field?</strong><p class="answer">8-byte units.</p></div><div class="q"><strong>Q3. What does MF = 0 indicate?</strong><p class="answer">This is the final fragment of the datagram.</p></div><div class="q"><strong>Q4. What does DF = 1 mean?</strong><p class="answer">The packet must not be fragmented by IPv4 routers.</p></div><div class="q"><strong>Q5. Where does IPv4 reassembly normally occur?</strong><p class="answer">At the destination host.</p></div><div class="q"><strong>Q6. A fragment begins 2400 payload bytes from the start. What offset is recorded?</strong><p class="answer">2400 ÷ 8 = 300.</p></div><div class="q"><strong>Q7. Can an IPv6 router fragment a packet?</strong><p class="answer">No. The source can fragment using the IPv6 Fragment extension header.</p></div>""")}
{sec("12. Quick revision", """<ul><li><strong>Fragmentation:</strong> split an oversized IP datagram to fit a smaller MTU.</li><li><strong>MTU:</strong> maximum packet size supported by a link.</li><li><strong>Identification:</strong> associates fragments with the original datagram.</li><li><strong>DF:</strong> Don't Fragment.</li><li><strong>MF:</strong> More Fragments; 0 indicates the final fragment.</li><li><strong>Fragment Offset:</strong> position in original payload, in 8-byte units.</li><li><strong>Reassembly:</strong> normally at the destination.</li><li><strong>IPv4:</strong> routers may fragment when permitted.</li><li><strong>IPv6:</strong> routers do not fragment; source may use a Fragment extension header.</li></ul><div class="good"><strong>Exam checklist:</strong> practise the numerical example, write the offset unit correctly, and clearly state the difference between IPv4 and IPv6 fragmentation.</div>""")}
</main><footer>CN Notes · Unit 2 · Topic 23 — Packet Fragmentation</footer></body></html>"""

OUT.write_text(page, encoding="utf-8")
print(f"Created: {OUT}")
